import os

# Search for any directory named 'reports' in the current tree
def find_reports_dir(start_path='.'):
    for root, dirs, files in os.walk(start_path):
        if 'reports' in dirs:
            return os.path.join(root, 'reports')
    return None

reports_dir = find_reports_dir()
print(f"Found reports_dir: {reports_dir}")

if reports_dir:
    total_sum = 0
    for filename in os.listdir(reports_dir):
        filepath = os.path.join(reports_dir, filename)
        if os.path.isfile(filepath):
            try:
                with open(filepath, 'r') as f:
                    lines = f.readlines()
                    if lines:
                        last_line = lines[-1].strip()
                        if last_line.startswith('TOTAL:'):
                            value = int(last_line.split(':')[1].strip())
                            total_sum += value
